def mode(numbers: List[int]) -> List[int]:
    """ For a given list of numbers find the most occuring number
    >>> mode([1, 2, 3, 3, 4, 4, 4])
    [4]
    >>> mode([1, 1, 2, 2])
    [1, 2]
    """
    count = {}
    for n in numbers:
        if n not in count:
            count[n] = 1
        else:
            count[n] += 1
    result = sorted(count, key=count.get, reverse=True)
    return result

