def parse_paren_groups(paren_string: str) -> int:
    """ Given a parenthesis group, parse the number of levels of nesting.

    >>> parse_paren_groups('(()())')
    2
    """
    nested_count = 0
    parenthesis_length = len(paren_string)
    left_count = 0
    for i in range(parenthesis_length):
        if paren_string[i] == '(':
            left_count += 1
        else:
            if left_count == 0:
                nested_count += 1
            else:
                left_count -= 1
    return nested_count


