def has_close_elements(numbers: List[float], threshold: float) -> bool:
    min_n = min(numbers)
    min_index = numbers.index(min_n)
    numbers.remove(min_n)
    for a in numbers:
        if abs(a - min_n) <= threshold:
            return True
    numbers.insert(min_index, min_n)
    for b in numbers:
        if abs(b - min_n) <= threshold:
            return True
    return False

    if (len(numbers) < 2):
        return False
    min = numbers[0]
    max = numbers[0]
    for index in range(1, len(numbers)):
        if abs(numbers[index] - min) < threshold:
            return True
        elif abs(numbers[index] - max) < threshold:
            return True
        elif numbers[index] < min:
            min = numbers[index]
        elif numbers[index] > max:
            max = numbers[index]
    return False


