def max_levels(length: int, string: str) -> int:
    """ Return the length of the deepest nesting in a string of parentheses.
    """
    length = length + 1
    if length == 1:
        return length
    left = length
    right = length
    for char in string:
        if char == "(":
            left -= 1
        elif char == ")":
            right -= 1
        else:
            pass
    if right < left:
        return right
    return left


